import {aiTimeSource} from './planning-ai-time-data.js';
export const aiTimeDefinitions={aiTime:{title:'Read the work-time survey, then enter an independent paid-work scenario',fields:[
 ['aiHours','Independent usable time released per week (hours)',3,0,10,.5],
 ['aiWeeks','Weeks in the independent work scenario',46,1,52,1],
 ['aiPaidShare','Share of released time converted into additional paid hours (%)',50,0,100,10],
 ['aiReceiptRate','Additional gross cash received per converted hour (CAD)',50,0,200,10],
 ['aiToolCost','Annual out-of-pocket tool cost (CAD)',240,0,2400,120]
]}};
export function aiTimeCashScenario(i,share=i.aiPaidShare,cost=i.aiToolCost){
 const released=i.aiHours*i.aiWeeks,paid=released*share/100,gross=paid*i.aiReceiptRate;
 return {released,paid,gross,cost,change:gross-cost,noExtraPayChange:-cost};
}
export function aiTimeResult(kind,i){
 if(kind!=='aiTime')throw Error('Unknown AI-time topic.');
 const p=aiTimeCashScenario(i),hours=aiTimeSource.groups[0],uses=aiTimeSource.groups[1],source={source:aiTimeSource.reportUrl,sourceLabel:'Bank of Canada · CSCE 2026 Q3, Box 1 and linked data'};
 return {metrics:[['Survey · additional hours estimated without AI, interpolated median',hours.rows[1].value,'decimal'],['Independent scenario · additional gross cash receipts',p.gross,'money'],['Independent scenario · cash change after tool cost, before personal tax',p.change,'money']],note:'The first two panels reproduce published aggregate survey results from the Bank of Canada’s CSCE 2026 Q3 AI-work module, released 19 October 2026 and retrieved 25 October. Online collection was 5–27 August; follow-up interviews were 24 August–4 September. Hours are interpolated medians: active weekly use is estimated from reported duration categories and frequency, while additional time without AI is a respondent estimate of a counterfactual. The uses question permits multiple answers, so its shares overlap and need not sum to 100%. These are categorical observations, not a daily time series. No sample counts, response overlaps, causal productivity effect or earnings gain are inferred. The last three panels use independently entered weekly time, weeks, paid conversion, gross receipts per converted hour and out-of-pocket annual cost. They do not copy any survey median or response share into the scenario. All additional paid-work receipts are assumed actually received within this one-year horizon; no unpaid invoice or collection lag is added. A fixed-pay path assumes no overtime, bonus or pay rise and therefore has no extra receipts, but bears the same entered out-of-pocket cost. Cash change after that cost is before personal tax, other work costs and benefit changes; it is not take-home pay, business profit, a tax deduction or proof of affordability. No monetary value is imputed to leisure, quality, learning or the person’s existing salary.',charts:[
  {...source,id:'ai-time-survey-hours',type:'bar',evidence:'Official survey results',title:'Two survey hour measures describe different questions, not a subtraction exercise',unit:'decimal',tableUnit:'hours per week',unitLabel:'Hours per week · interpolated medians · 2026 Q3 AI-work module',rows:hours.rows.map(r=>({...r})),note:'The active-use median comes from respondent-level estimates using duration-category midpoints and reported weekly frequency. The source assigns 7.5 hours to the open-ended daily category above six hours. The second median summarizes estimated additional time needed without AI. Neither is a directly timed experiment, and subtracting these aggregate medians does not establish an individual net saving.'},
  {...source,id:'ai-time-survey-uses',type:'bar',evidence:'Official survey results · multiple answers allowed',title:'Workers could report several uses of time, so these shares are not pie slices',unit:'percent',unitLabel:'Share of respondents to the saved-time question (%) · multiple selection',rows:uses.rows.map(r=>({label:r.label,value:r.value/100})),note:'The source asks respondents to check all applicable uses of time in the AI-work module. Keep that question-specific respondent denominator; these are not shares of all Canadians or mutually exclusive worker groups. The extract does not reveal how answers overlap, how much time went to each use or how many workers earned additional pay.'},
  {id:'ai-time-cash-bridge',type:'waterfall',title:'Convert only the independently selected paid hours into additional cash receipts',unit:'money',unitLabel:'CAD within the independent one-year scenario · before personal tax',rows:[{label:'Additional gross cash actually received',value:p.gross},{label:'Out-of-pocket annual tool cost',value:-p.cost}],totalLabel:'Cash change after tool cost, before personal tax',note:'Gross receipts = independently entered released hours per week × weeks × paid conversion × receipts per converted hour. The tool cost is deducted once. No wage is assigned automatically to every released hour, and no time-use survey percentage is treated as a paid-work conversion rate.'},
  {id:'ai-time-pay-arrangements',type:'signedbar',title:'A fixed-pay arrangement can release time without creating extra income',unit:'money',unitLabel:'CAD cash change after the same tool cost · before personal tax',rows:[{label:'Extra paid-work scenario',value:p.change},{label:'Fixed pay · no additional compensation',value:p.noExtraPayChange}],note:'These are two defined compensation arrangements using the same out-of-pocket annual cost. The fixed-pay path has no extra receipts by assumption. It can still have noncash benefits, which are not priced here. Negative values mean the tool cost exceeds additional receipts within this narrow comparison, not that the person’s entire household income is negative.'},
  {id:'ai-time-paid-conversion-grid',type:'heatmap',signed:true,title:'Test paid conversion and out-of-pocket cost without assuming either is guaranteed',unit:'money',unitLabel:'Cash change in CAD · after tool cost, before personal tax',columns:['$0 fee','$120 fee','$240 fee','$480 fee'],rows:[0,25,50,75,100].map(share=>({label:share+'% paid',values:[0,120,240,480].map(cost=>aiTimeCashScenario(i,share,cost).change)})),note:'Rows replace the share of independently entered released time converted into additional paid hours; columns replace annual out-of-pocket tool cost. Weekly time, weeks and receipts per converted hour remain selected. No probability is assigned to conversion or revenue, and the survey panels remain fixed.'}
 ]};
}
